import type { AdapterName, EIP1193Provider, TypedData } from '@tronweb3/abstract-adapter-evm';
import {
    Adapter,
    WalletReadyState,
    WalletNotFoundError,
    WalletConnectionError,
    isInMobileBrowser,
    WalletDisconnectedError,
} from '@tronweb3/abstract-adapter-evm';
import { getTokenPocketEvmProvider, openTokenPocketWithDeeplink, supportTokenPocketEvm } from './utils.js';

export interface TokenPocketAdapterOptions {
    useDeeplink?: boolean;
}
export const TokenPocketAdapterName = 'TokenPocket' as AdapterName<'TokenPocket'>;
export class TokenPocketAdapter extends Adapter {
    name = TokenPocketAdapterName;
    url = 'https://tokenpocket.pro/';
    icon =
        'data:image/svg+xml;base64,';
    readyState = WalletReadyState.Loading;
    address: string | null = null;
    connecting = false;
    options: TokenPocketAdapterOptions;

    constructor(options: TokenPocketAdapterOptions = { useDeeplink: true }) {
        super();
        this.options = options;
        const provider = getTokenPocketEvmProvider();
        if (provider) {
            this.readyState = WalletReadyState.Found;
            this.listenEvents(provider);
            this.autoConnect(provider);
        } else {
            this.getProvider().then((res) => {
                if (res) {
                    this.readyState = WalletReadyState.Found;
                    this.listenEvents(res);
                    this.autoConnect(res);
                } else {
                    this.readyState = WalletReadyState.NotFound;
                }
                this.emit('readyStateChanged', this.readyState);
            });
        }
    }

    protected getInjectedProvider = getTokenPocketEvmProvider;
    async connect() {
        if (this.options.useDeeplink !== false) {
            if (isInMobileBrowser() && !supportTokenPocketEvm()) {
                openTokenPocketWithDeeplink();
                return '';
            }
        }
        this.connecting = true;

        const provider = await this.getProvider();
        if (!provider) {
            throw new WalletNotFoundError();
        }
        let accounts: string[] = [];
        try {
            accounts = await provider.request<undefined, string[]>({ method: 'eth_requestAccounts' });
        } catch (e: any) {
            throw new WalletConnectionError('Connection error: ' + e?.message, e);
        }
        if (!accounts.length) {
            throw new WalletConnectionError('No accounts is avaliable.');
        }
        this.address = accounts[0];
        this.connecting = false;
        this.emit('accountsChanged', accounts);
        return this.address as string;
    }
    async signTypedData(params: { typedData: TypedData; address?: string }): Promise<string> {
        const provider = await this.prepareProvider();
        if (!this.connected) {
            throw new WalletDisconnectedError();
        }
        return provider.request({
            method: 'eth_signTypedData_v4',
            // Use JSON.stringify to wrap typedData or it will have a display issue when signing.
            params: [params.address || this.address, JSON.stringify(params.typedData)],
        });
    }
}
